import { randomUUID } from "node:crypto";
import { constants } from "node:fs";
import { mkdir, open, rename, unlink, writeFile } from "node:fs/promises";
import { isAbsolute, join } from "node:path";
import { Readable } from "node:stream";
import { AwsClient } from "aws4fetch";

export interface AttachmentStorage {
  put(key: string, data: Uint8Array<ArrayBuffer>, contentType: string): Promise<void>;
  read(key: string): Promise<Response>;
  remove(key: string): Promise<boolean>;
}

/** Keys are generated by the app; neither filenames nor arbitrary database paths are accepted. */
function validKey(key: string) {
  if (!/^attachments\/[0-9a-f-]{36}\.(webp|bin)$/.test(key)) throw new Error("Invalid attachment storage key");
  return key;
}

export function localAttachmentStorage(directory: string): AttachmentStorage {
  if (!isAbsolute(directory)) throw new Error("ATTACHMENT_DIR must be an absolute private path");
  const path = (key: string) => join(directory, validKey(key));
  return {
    async put(key, data) {
      const target = path(key);
      await mkdir(join(directory, "attachments"), { recursive: true, mode: 0o700 });
      const temporary = `${target}.${randomUUID()}.tmp`;
      try {
        await writeFile(temporary, data, { flag: "wx", mode: 0o600 });
        await rename(temporary, target);
      } finally {
        await unlink(temporary).catch((error: NodeJS.ErrnoException) => { if (error.code !== "ENOENT") throw error; });
      }
    },
    async read(key) {
      try {
        const handle = await open(path(key), constants.O_RDONLY | constants.O_NOFOLLOW);
        try {
          const info = await handle.stat();
          if (!info.isFile()) { await handle.close(); return new Response(null, { status: 404 }); }
          return new Response(Readable.toWeb(handle.createReadStream()) as ReadableStream<Uint8Array>, {
            headers: { "Content-Length": String(info.size) },
          });
        } catch (error) { await handle.close(); throw error; }
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === "ENOENT" || (error as NodeJS.ErrnoException).code === "ELOOP") return new Response(null, { status: 404 });
        throw error;
      }
    },
    async remove(key) {
      try { await unlink(path(key)); return true; }
      catch (error) { if ((error as NodeJS.ErrnoException).code === "ENOENT") return true; throw error; }
    },
  };
}

export function configuredAttachmentStorage(): AttachmentStorage | null {
  const { ATTACHMENT_DIR, R2_ENDPOINT, R2_BUCKET, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY } = process.env;
  if (ATTACHMENT_DIR) {
    if (R2_ENDPOINT || R2_BUCKET || R2_ACCESS_KEY_ID || R2_SECRET_ACCESS_KEY) throw new Error("Choose ATTACHMENT_DIR or S3 settings, not both");
    return localAttachmentStorage(ATTACHMENT_DIR);
  }
  if (!R2_ENDPOINT || !R2_BUCKET || !R2_ACCESS_KEY_ID || !R2_SECRET_ACCESS_KEY) return null;
  const client = new AwsClient({ accessKeyId: R2_ACCESS_KEY_ID, secretAccessKey: R2_SECRET_ACCESS_KEY, service: "s3", region: "auto" });
  const url = (key: string) => `${R2_ENDPOINT.replace(/\/$/, "")}/${R2_BUCKET}/${validKey(key)}`;
  return {
    async put(key, data, contentType) {
      const result = await client.fetch(url(key), { method: "PUT", body: data, headers: { "Content-Type": contentType, "Content-Length": String(data.byteLength) } });
      if (!result.ok) throw new Error("Attachment object write failed");
    },
    read: (key) => client.fetch(url(key)),
    async remove(key) {
      const result = await client.fetch(url(key), { method: "DELETE" });
      return result.ok || result.status === 404;
    },
  };
}
